import os
import torch


class Config:
    """
    Configuration class for the Histopathologic Cancer Detection task.
    Stores all hyperparameters, file paths, and system settings.
    """

    # --- System & Reproducibility ---
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # 12 vCPUs available; 4 workers is usually optimal for data loading to avoid overhead
    NUM_WORKERS = 4

    # --- File Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # CSV Files generated by metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for checkpoints and cache
    WORKING_DIR = "./working/idea_2"

    # Submission directory
    SUBMISSION_DIR = "./submission"

    # Specific file paths
    MODEL_CHECKPOINT = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Hyperparameters ---
    # Source image dimensions
    SRC_SIZE = (96, 96)
    # Input dimensions for the model (Center Crop size)
    INPUT_SIZE = (64, 64)
    # Center Region of Interest (for reference/logic)
    ROI_SIZE = (32, 32)

    # Normalization statistics derived from EDA
    # Mean (R, G, B) and Std (R, G, B)
    DATA_MEAN = [0.7035, 0.5476, 0.6975]
    DATA_STD = [0.2388, 0.2821, 0.2159]

    # Debugging
    DEBUG = False
    DEBUG_SAMPLES = 2000  # Number of samples to use if DEBUG is True

    # --- Model Hyperparameters ---
    MODEL_NAME = "convnext_tiny"  # Using ConvNeXt-Tiny as modern CNN backbone
    PRETRAINED = True
    NUM_CLASSES = 1

    # Regularization inside model
    DROP_RATE = 0.0
    DROP_PATH_RATE = 0.1  # Stochastic depth

    # --- Training Hyperparameters ---
    NUM_EPOCHS = 15
    BATCH_SIZE = 128
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2  # Standard for AdamW

    # Mixup Regularization
    USE_MIXUP = True
    MIXUP_ALPHA = 0.2

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 5

    # Test Time Augmentation
    TTA_VIEWS = 8  # 8-view TTA (Dihedral group D4)

    @classmethod
    def setup(cls):
        """
        Creates necessary output directories if they don't exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Execute setup upon import to ensure environment is ready
Config.setup()
